  "py": "\"\"\"Use case 3 (Hard): a nightly import that fans out to child workflows and keeps its history bounded with Continue-As-New.\"\"\"\nimport asyncio\nfrom dataclasses import dataclass\nfrom datetime import timedelta\n\nfrom temporalio import activity, workflow\n\nTASK_QUEUE = \"imports\"\nTOTAL_RECORDS = 100\nPAGE_SIZE = 10\nDONE: list[int] = []  # page numbers processed (stand-in for rows written)\n\n\n@activity.defn\nasync def import_page(page: int, delay: float) -> int:\n    await asyncio.sleep(delay)\n    DONE.append(page)\n    return PAGE_SIZE\n\n\n@dataclass\nclass PageInput:\n    page: int\n    delay: float = 0.0\n\n\n@workflow.defn\nclass PageWorkflow:\n    @workflow.run\n    async def run(self, p: PageInput) -> int:\n        return await workflow.execute_activity(import_page, args=[p.page, p.delay], start_to_close_timeout=timedelta(seconds=30))\n\n\n@dataclass\nclass ImportInput:\n    job: str\n    next_page: int = 0\n    imported: int = 0  # carried across runs\n    pages_per_run: int = 4  # small on purpose so the test sees several runs\n    page_delay: float = 0.0\n    parent_close: str = \"TERMINATE\"  # or ABANDON / REQUEST_CANCEL\n\n\n@workflow.defn\nclass ImportWorkflow:\n    @workflow.run\n    async def run(self, inp: ImportInput) -> int:\n        policy = workflow.ParentClosePolicy[inp.parent_close]\n        last_page = TOTAL_RECORDS // PAGE_SIZE\n        done_this_run = 0\n        while inp.next_page < last_page:\n            # 2 children at a time; deterministic child IDs, so a replayed or repeated start cannot create a duplicate\n            batch = range(inp.next_page, min(inp.next_page + 2, last_page))\n            counts = await asyncio.gather(*[\n                workflow.execute_child_workflow(\n                    PageWorkflow.run, PageInput(p, inp.page_delay),\n                    id=f\"{inp.job}-page-{p}\", parent_close_policy=policy)\n                for p in batch])\n            inp.imported += sum(counts)\n            inp.next_page += len(batch)\n            done_this_run += len(batch)\n            # continue when the server says history is getting big (or, here, after a fixed number of pages)\n            if inp.next_page < last_page and (workflow.info().is_continue_as_new_suggested() or done_this_run >= inp.pages_per_run):\n                workflow.continue_as_new(inp)\n        return inp.imported",
  "ts": "// ===== import.job.ts =====\n/* Use case 3 (Hard): a nightly import that fans out to child workflows and keeps its history bounded with Continue-As-New. */\nimport { continueAsNew, executeChild, ParentClosePolicy, proxyActivities, workflowInfo } from '@temporalio/workflow';\nimport type * as activities from './import.job.activities';\n\nconst { importPage } = proxyActivities<typeof activities>({ startToCloseTimeout: '30 seconds' });\n\nconst TOTAL_RECORDS = 100;\nconst PAGE_SIZE = 10;\n\nexport async function pageWorkflow(p: { page: number; delayMs: number }): Promise<number> {\n  return importPage(p.page, p.delayMs);\n}\n\nexport interface ImportInput {\n  job: string;\n  nextPage?: number;\n  imported?: number; // carried across runs\n  pagesPerRun?: number; // small on purpose so the test sees several runs\n  pageDelayMs?: number;\n  parentClose?: 'TERMINATE' | 'ABANDON' | 'REQUEST_CANCEL';\n}\n\nexport async function importWorkflow(input: ImportInput): Promise<number> {\n  const { job, pagesPerRun = 4, pageDelayMs = 0, parentClose = 'TERMINATE' } = input;\n  let nextPage = input.nextPage ?? 0;\n  let imported = input.imported ?? 0;\n  const lastPage = TOTAL_RECORDS / PAGE_SIZE;\n  let doneThisRun = 0;\n\n  while (nextPage < lastPage) {\n    // 2 children at a time; deterministic child IDs, so a replayed or repeated start cannot create a duplicate\n    const batch = [nextPage, nextPage + 1].filter((p) => p < lastPage);\n    const counts = await Promise.all(batch.map((p) =>\n      executeChild(pageWorkflow, {\n        workflowId: `${job}-page-${p}`,\n        args: [{ page: p, delayMs: pageDelayMs }],\n        parentClosePolicy: ParentClosePolicy[parentClose],\n      })));\n    imported += counts.reduce((a, b) => a + b, 0);\n    nextPage += batch.length;\n    doneThisRun += batch.length;\n    // continue when the server says history is getting big (or, here, after a fixed number of pages)\n    if (nextPage < lastPage && (workflowInfo().continueAsNewSuggested || doneThisRun >= pagesPerRun)) {\n      await continueAsNew<typeof importWorkflow>({ ...input, nextPage, imported });\n    }\n  }\n  return imported;\n}\n\n// ===== import.job.activities.ts =====\nexport const DONE: number[] = []; // page numbers processed (stand-in for rows written)\nexport const PAGE_SIZE = 10;\n\nexport async function importPage(page: number, delayMs: number): Promise<number> {\n  await new Promise((r) => setTimeout(r, delayMs));\n  DONE.push(page);\n  return PAGE_SIZE;\n}"
